package com.nm.fragmentsclean.userApplicationContext.write.adapters.primary.springboot.controllers;

import com.nm.fragmentsclean.sharedKernel.adapters.primary.springboot.CommandBus;import com.nm.fragmentsclean.sharedKernel.businesslogic.commandStatus.BusinessCommandRejectedException;import com.nm.fragmentsclean.sharedKernel.businesslogic.media.ImageUploadRejectedException;import com.nm.fragmentsclean.userApplicationContext.write.businesslogic.usecases.*;import java.util.UUID;import org.springframework.http.ResponseEntity;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/users/me/avatar")
public final class WriteAvatarController{private final IssueAvatarUploadIntent intents;private final ConfirmAvatarUpload confirmations;private final CommandBus commands;public WriteAvatarController(IssueAvatarUploadIntent intents,ConfirmAvatarUpload confirmations,CommandBus commands){this.intents=intents;this.confirmations=confirmations;this.commands=commands;}@PostMapping("/upload-intents")ResponseEntity<AvatarUploadIntent> intent(@RequestBody AvatarUploadIntentRequest body,@AuthenticationPrincipal Jwt jwt){if(body.mediaId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"mediaId is required");return ResponseEntity.status(201).body(intents.issue(body.mediaId(),user(jwt),body.contentType(),body.size()));}@PostMapping("/{mediaId}/confirm")ResponseEntity<Void> confirm(@PathVariable UUID mediaId,@RequestBody AvatarCommandRequest body,@AuthenticationPrincipal Jwt jwt){if(body.commandId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"commandId is required");try{confirmations.confirm(body.commandId(),mediaId,user(jwt),body.at());}catch(ImageUploadRejectedException rejected){throw new BusinessCommandRejectedException(rejected.code(),rejected.getMessage());}return ResponseEntity.accepted().build();}@DeleteMapping ResponseEntity<Void> remove(@RequestBody AvatarCommandRequest body,@AuthenticationPrincipal Jwt jwt){if(body.commandId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"commandId is required");commands.dispatch(new RemoveAvatarCommand(body.commandId(),user(jwt),body.at()));return ResponseEntity.accepted().build();}private static UUID user(Jwt jwt){return UUID.fromString(jwt.getSubject());}}
